from core.prompts.domain_function_library import FractionOps, PolynomialOps, RadicalOps
from core.skill_policies.radical_logic import RadicalLogicEngine

def generate(level=1, **kwargs):
    radicand = 27

    simplified_coefficient, square_free_radicand = RadicalLogicEngine.simplify_radical(radicand)

    question_text = f"Rewrite {simplified_coefficient} * sqrt({radicand}) in simplest radical form as coefficient * sqrt(square-free radicand)." if simplified_coefficient != 1 else f"Rewrite sqrt({radicand}) in simplest radical form."

    correct_answer = {
        "coefficient": int(simplified_coefficient),
        "radicand": square_free_radicand
    }

    oracle_payload = {"radicand": radicand}

    return {
        "question_text": question_text,
        "correct_answer": correct_answer,
        "oracle_payload": oracle_payload
    }

